r=random.Random(0); err=0; n=0
for E in (2,8,64):
 for k in (1,E//2,E):
  for _ in range(100):
   z=[r.uniform(-20,20) for i in range(E)]; ix=sorted(range(E),key=lambda i:z[i],reverse=True)[:k]
   a=[math.exp(v-max(z)) for v in z]; p=[v/sum(a) for v in a]; old=[p[i]/sum(p[j] for j in ix) for i in ix]
   b=[math.exp(z[i]-max(z[j] for j in ix)) for i in ix]; new=[v/sum(b) for v in b]
   err=max(err,max(abs(x-y) for x,y in zip(old,new))); n+=1
print({'cases':n,'max_abs_error':err,'all_expert_indices':8,'fused_output_experts':2})

